        "text": "Use a look-away-and-return sequence. The torch flame silhouettes and brightness should continue evolving while offscreen.",
        "chunks": [
          {
            "chunk_id": "c01",
            "action": {
              "text": "Turn away from the torch flame silhouettes and brightness while it is still visible."
            }
          },
          {
            "chunk_id": "c02",
